                chain for chain in chains if chain[ID] == fork_id
            )
            if material[CP_DIGEST] != receipt_digest:
                raise _fork_proof_invalid(
                    f"{where} receiptDigest does not match the chain named "
                    f"by {fork_id!r}"
                )
            # Walk the actual chain path: a named chain must cross this
            # edge -- a node equal to ``upstream`` followed by a hop whose
            # audience is one of the fork's audiences.
            node = receipt_digest
            hop_materials = material[DELEGATION_HOPS]
            crosses = False
            for hop_index, hop_material in enumerate(hop_materials):
                if node == upstream:
