            item_report = by_id.get(fork_id)
            if item_report is None:
                raise _fork_proof_invalid(
                    f"{where} id {fork_id!r} does not match a report item"
                )
            result = item_report[VERDICT_ITEM_RESULT]
            if not isinstance(result, dict):
                raise _fork_proof_invalid(
                    f"{where} id {fork_id!r} names a chain that never "
                    "verified"
                )
            material = next(
                chain for chain in chains if chain[ID] == fork_id
            )
            if material[CP_DIGEST] != receipt_digest:
                raise _fork_proof_invalid(
                    f"{where} receiptDigest does not match the chain named "
                    f"by {fork_id!r}"
                )
            # Walk the actual chain path: a named chain must cross this
            # edge -- a node equal to ``upstream`` followed by a hop whose
            # audience is one of the fork's audiences.
            node = receipt_digest
            hop_materials = material[DELEGATION_HOPS]
            crosses = False
            for hop_index, hop_material in enumerate(hop_materials):
                if node == upstream:
                    audience = result[DELEGATION_HOPS][hop_index][
                        DELEGATION_AUDIENCE
                    ]
                    if audience in audience_set:
                        crosses = True
                        break
                node = hop_material
            if not crosses:
                raise _fork_proof_invalid(
                    f"{where} chain {fork_id!r} does not cross the fork edge"
                )
            fork_ids.add(fork_id)

    if fork_ids != conflicted:
        raise _fork_proof_invalid(
            "the fork id sets must equal the conflicted report items"
        )
    return report


def _validated_fork_chains(chains: object) -> list[dict]:
    """Validate the bound chain material summary into fresh ordered dicts.

    Each entry must carry exactly ``id`` (a non-empty str), ``digest``
    (64 lowercase hex characters), ``target`` (a non-empty str) and
    ``hops`` (a non-empty list of 64-char lowercase hex digests).  Every
    fault is an :class:`InvalidReceiptForkProofError`.
    """
    if not isinstance(chains, list):
        raise TypeError("payload chains must be a list")
    if not chains:
        raise _fork_proof_invalid("payload chains must be non-empty")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, chain in enumerate(chains):
        where = f"chain {position}"
        if not isinstance(chain, dict):
            raise _fork_proof_invalid(f"{where} must be an object")
        if set(chain.keys()) != _FORK_CHAIN_KEYS:
            raise _fork_proof_invalid(
                f"{where} must contain exactly the keys 'id', 'digest', "
                "'target' and 'hops'"
            )
        chain_id = chain[ID]
        if not isinstance(chain_id, str) or chain_id == "":
            raise _fork_proof_invalid(f"{where} id must be a non-empty str")
        if chain_id in seen_ids:
            raise _fork_proof_invalid(f"{where} repeats an id")
        seen_ids.add(chain_id)
        digest = chain[CP_DIGEST]
        if not _is_digest(digest):
            raise _fork_proof_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        target = chain[DELEGATION_TARGET]
        if not isinstance(target, str) or target == "":
            raise _fork_proof_invalid(f"{where} target must be a non-empty str")
        hops = chain[DELEGATION_HOPS]
        if not isinstance(hops, list) or not hops:
            raise _fork_proof_invalid(
                f"{where} hops must be a non-empty list"
            )
        if any(not _is_digest(hop) for hop in hops):
            raise _fork_proof_invalid(
                f"{where} hops must be 64 lowercase hex characters"
            )
        validated.append(
            {
                ID: chain_id,
                CP_DIGEST: digest,
                DELEGATION_TARGET: target,
                DELEGATION_HOPS: list(hops),
            }
        )
    return validated

